const LBL = { policy: 'Політики', howto: 'Інструкції', hr: 'HR і податки', role: 'Профілі посад', markup: 'Розмітка' };
const cat = $('Set Category').first().json.category;
const retried = $('Ask DocuMindy (All Categories)').isExecuted;
const ev = $('Normalize Chat Event').first().json;
const r = $input.first().json;
let text = String(r.text || '').trim();
const notFound = text.includes('[NO_ANSWER]') || text.startsWith('На жаль, у внутрішніх');
text = text.replace('[NO_ANSWER]', '').trim();
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let html = esc(text).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/^\s*[*-]\s+/gm, '• ').replace(/\n/g, '<br>');
if (html.length > 3500) html = html.slice(0, 3500) + '…';
const pages = {};
(r.sourceDocuments || []).forEach(d => {
  const m = d.metadata || {};
  const f = m.fileName || m.source || m.name;
  if (!f) return;
  (pages[f] = pages[f] || new Set()).add(m.loc && m.loc.pageNumber);
});
const src = notFound ? [] : Object.keys(pages).slice(0, 3).map(f => {
  const p = Array.from(pages[f]).filter(Boolean).sort((a, b) => a - b);
  return '📌 ' + esc(f.replace(/\.pdf$/i, '')) + (p.length ? ', стор. ' + p.join(', ') : '');
});
const hint = (!retried && LBL[cat]) ? (notFound ? '🗂 Шукав у категорії «' + LBL[cat] + '». Щоб шукати всюди, почніть запит із «всі:»' : '🗂 Категорія: ' + LBL[cat]) : '';
if (hint) src.push(hint);
const widgets = [{ textParagraph: { text: html } }];
if (src.length) widgets.push({ divider: {} }, { textParagraph: { text: '<font color="#808080">' + src.join('<br>') + '</font>' } });
const FB_URL = '<WEBHOOK_URL>';
const topFile = ((r.sourceDocuments || [])[0] || {}).metadata?.fileName || '';
const fbp = v => [{ key: 'rating', value: v }, { key: 'question', value: String(ev.chatInput).slice(0, 150) }, { key: 'source', value: String(topFile).slice(0, 80) }, { key: 'category', value: (cat && cat !== 'all') ? cat : '' }];
widgets.push({ buttonList: { buttons: [{ text: '👍', onClick: { action: { function: FB_URL, parameters: fbp('up') } } }, { text: '👎', onClick: { action: { function: FB_URL, parameters: fbp('down') } } }] } });
const body = { cardsV2: [{ cardId: 'documindyAnswer', card: { header: { title: 'DocuMindy', subtitle: 'Корпоративний асистент' }, sections: [{ widgets }] } }] };
const hash = s => { let a = 0xdeadbeef, b = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); a = Math.imul(a ^ c, 2654435761); b = Math.imul(b ^ c, 1597334677); } a = Math.imul(a ^ (a >>> 16), 2246822507) ^ Math.imul(b ^ (b >>> 13), 3266489909); b = Math.imul(b ^ (b >>> 16), 2246822507) ^ Math.imul(a ^ (a >>> 13), 3266489909); return (4294967296 * (2097151 & b) + (a >>> 0)).toString(36); };
const first = (r.sourceDocuments || [])[0] || {};
const fm = first.metadata || {};
const log = {
  askedAt: new Date().toISOString(),
  userHash: hash('documindy|' + String(ev.sessionId).split('|').pop()),
  question: String(ev.chatInput).slice(0, 500),
  answered: !notFound,
  topSource: fm.fileName || '',
  topPage: (fm.loc && fm.loc.pageNumber) || 0,
  sourceCount: (r.sourceDocuments || []).length,
  answerChars: text.length
};
return [{ json: { space: ev.space, body, log } }];

const ev = $('Normalize Chat Event').first().json;
const body = { text: 'Сервіс DocuMindy тимчасово недоступний. Спробуйте ще раз за кілька хвилин.' };
return [{ json: { space: ev.space, body } }];

const ev = $('Normalize Chat Event').first().json;
const cmd = ev.command;
const hits = ($input.first().json.result?.hits) || [];
const LBL = { policy: 'Політики та процедури', howto: 'Інструкції до систем', hr: 'HR і податки', role: 'Профілі посад', markup: 'Розмітка (клієнтські інструкції)' };
const PFX = { policy: 'політики:', howto: 'інструкції:', hr: 'hr:', role: 'посади:', markup: 'розмітка:' };
const DESC = { policy: 'безпека, доступи, дисципліна, кодекс поведінки', howto: 'Redmine, пошта, LMS, 1С, ЕЦП', hr: 'відпустки, податки, довідки, Performance Review', role: 'обов\'язки позицій', markup: 'правила розмітки даних для клієнтських проєктів' };
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sec = (header, html) => ({ header, widgets: [{ textParagraph: { text: html } }] });
if (cmd === 'guide') {
  const sections = [
    sec('Як питати', 'Пишіть звичайним реченням і конкретно. Називайте проєкт, систему чи документ («у проєкті <назва>», «в Redmine»).<br>Питайте українською, російською або англійською: відповідь буде мовою запитання.<br>Уточнення працюють у тому ж чаті: «а де це написано?». Якщо запитання загальне, я перепитаю.'),
    sec('Префікси категорій', '<b>політики:</b> безпека, процедури, дисципліна<br><b>інструкції:</b> Redmine, пошта, LMS, 1С, ЕЦП<br><b>hr:</b> або <b>податки:</b> відпустки, декларування, довідки<br><b>посади:</b> профілі посад<br><b>розмітка:</b> інструкції з розмітки для клієнтських проєктів<br><b>всі:</b> без обмеження<br><br>Приклад: «розмітка: коли розмічати частково видимий об\'єкт у проєкті <назва>?»<br>Без префікса категорію я визначу сам. Якщо в категорії немає відповіді, шукаю по всій базі.'),
    sec('Команди', '<b>допомога</b> — коротка довідка<br><b>категорії</b> — список категорій<br><b>інструкції:</b> (лише префікс) — усі документи категорії<br><b>інструкція</b> — ця повна інструкція'),
    sec('Як читати відповідь', 'Під відповіддю: файл і сторінки, перевіряйте першоджерело для важливих рішень. «Категорія» показує, де я шукав. «Не знайшов» означає, що в документах цього немає: я не вигадую.'),
    sec('Оцінка і якщо не знайшов', 'Натисніть 👍 або 👎 під відповіддю: це допомагає покращувати бот.<br>Не знайшов? Переформулюйте, додайте назву проєкту, спробуйте інший префікс або «всі:», або зверніться до керівника чи HR.'),
    sec('Обмеження', 'Відповідаю лише за документами компанії. Приклади на скриншотах бачу як опис, а не як картинку: якщо відповідь залежить від прикладу, відкрийте документ. Не вводьте паролі та особисті дані.'),
  ];
  const body = { cardsV2: [{ cardId: 'documindyGuide', card: { header: { title: 'DocuMindy', subtitle: 'Інструкція з використання' }, sections } }] };
  return [{ json: { space: ev.space, body } }];
}
let html;
if (cmd.startsWith('list:')) {
  const c = cmd.slice(5);
  const names = hits.map(h => String(h.value).replace(/\.pdf$/i, '')).sort((a, b) => a.localeCompare(b, 'uk'));
  const max = c === 'markup' ? 25 : 50;
  html = '<b>' + esc(LBL[c]) + '</b>: документів ' + names.length + '<br>' + names.slice(0, max).map(n => '• ' + esc(n)).join('<br>')
    + (names.length > max ? '<br>…і ще ' + (names.length - max) : '')
    + '<br><br>Щоб шукати лише тут, почніть запит із «' + PFX[c] + '».';
} else {
  const cats = Object.keys(LBL).map(c => '• <b>' + esc(LBL[c]) + '</b> (' + PFX[c] + ') — ' + esc(DESC[c])).join('<br>');
  html = (cmd === 'help' ? 'Я — DocuMindy, корпоративний асистент. Відповідаю на запитання за внутрішніми документами та інструкціями з розмітки даних і вказую файл та сторінку.<br><br>' : '')
    + '<b>Категорії</b><br>' + cats
    + '<br><br>Просто напишіть запитання — категорію я визначу сам. Або почніть із префікса: «політики: …», «розмітка: …», «всі: …» (без обмеження). Напишіть лише префікс (наприклад «інструкції:»), щоб побачити документи категорії.<br><br>📖 Потрібна повна інструкція з використання? Напишіть <b>інструкція</b>.';
}
if (html.length > 3500) html = html.slice(0, 3500) + '…';
const body = { cardsV2: [{ cardId: 'documindyHelp', card: { header: { title: 'DocuMindy', subtitle: 'Довідка' }, sections: [{ widgets: [{ textParagraph: { text: html } }] }] } }] };
return [{ json: { space: ev.space, body } }];

const ev = $('Normalize Chat Event').first().json;
const text = ev.rating === 'up' ? 'Дякую за відгук 👍' : 'Дякую за відгук. Запишу, щоб покращити відповіді 👎';
return [{ json: { space: ev.space, body: { text } } }];
